def max_mono(g):
    h,w=len(g),len(g[0]); best=[0,None]
    for c in set(x for r in g for x in r):
        for i in range(h):
            for j in range(w):
                s=1
                while i+s<=h and j+s<=w and all(g[i+a][j+b]==c for a in range(s) for b in range(s)):
                    s+=1
                if s>best[0]: best[0],best[1]=s,(i,j,c)
    return best
